                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        stack.append(p)
            top = min(x for x, y in cells)
            left = min(y for x, y in cells)
            shape = tuple(sorted((x - top, y - left) for x, y in cells))
            result.append((color, cells, shape))
    return result

def transform(grid):
    out = [row[:] for row in grid]
    objects = _components(grid)
    references = [obj for obj in objects if obj[0] != 1]
    for color, cells, shape in objects:
