                        seen.add(p)
                        stack.append(p)
            result.append((color, cells, _shape(cells)))
    return result

def _shape(cells):
    top = min(r for r, c in cells)
    left = min(c for r, c in cells)
    return tuple(sorted((r - top, c - left) for r, c in cells))

def _rotate(shape):
    return _shape([(c, -r) for r, c in shape])

def _orients(shape):
    result = []
    for turns in range(4):
        if shape not in result:
            result.append(shape)
        shape = _rotate(shape)
    return result

def _distance(a, b):
    return min(abs(r - rr) + abs(c - cc) for r, c in a for rr, cc in b)

def transform(grid):
    out = [row[:] for row in grid]
    objects = _components(grid)
    targets = [obj for obj in objects if obj[0] == 1]
    refs = [obj for obj in objects if obj[0] != 1]
    classes = {}
    for ref in refs:
        key = min(_orients(ref[2]))
        classes.setdefault(key, []).append(ref)
    by_class = {}
    for target in targets:
        key = min(_orients(target[2]))
        by_class.setdefault(key, []).append(target)
    for key, group in by_class.items():
        candidates = classes.get(key, [])
        if not candidates:
            continue
        # Pair shape copies, preferring nearby objects while charging for rotation.
        n = min(len(group), len(candidates))
        best = None
        for chosen in permutations(candidates, n):
            cost = 0
            turns_total = 0
            for target, ref in zip(group[:n], chosen):
                orientations = _orients(ref[2])
                turns = min(i for i, s in enumerate(orientations) if s == target[2])
                cost += _distance(target[1], ref[1]) + 3 * turns
                turns_total += turns
